const body = $('Webhook AgroVenda').first().json.body || {};
const saleId = String(body.saleId || body.driveFolder?.saleId || '').trim();
const storeFolder = String(body.driveFolder?.storeFolder || body.client || 'Sem_Loja')
  .trim()
  .replace(/[^\w.\-À-ú ]+/gi, '_')
  .replace(/\s+/g, '_')
  .replace(/^_+|_+$/g, '')
  .slice(0, 80) || 'Sem_Loja';
if (!saleId) throw new Error('saleId ausente no webhook');
return [{
  json: {
    saleId,
    storeFolder,
    defaultTenantId: '139EdJ1P2DdUqyj0He1w41eBjE8PKCxq9',
    agroVendaRootId: '1QKum1pz3NW3ZDo1eKyu2_08B4KDLaIro'
  }
}];

const ctx = $('Contexto Path SaaS').first().json;
const hits = $input.all().map((i) => i.json).filter((j) => j && j.id && String(j.name || '') === ctx.storeFolder);
return [{
  json: {
    ...ctx,
    storeFolderId: hits[0]?.id || null,
    storeExists: Boolean(hits[0])
  }
}];

const resolved = $('Resolver Pasta Loja').first().json;
const created = $input.first()?.json;
const storeFolderId = resolved.storeExists ? resolved.storeFolderId : created?.id;
if (!storeFolderId) throw new Error('Pasta da loja não resolvida');
return [{ json: { ...resolved, storeFolderId, storeExists: true } }];

const store = $('Unificar Pasta Loja').first().json;
const hits = $input.all().map((i) => i.json).filter((j) => j && j.id && String(j.name || '') === store.saleId);
return [{
  json: {
    ...store,
    folderId: hits[0]?.id || null,
    folderExists: Boolean(hits[0])
  }
}];

const resolved = $('Resolver Pasta VP').first().json;
const created = $input.first()?.json;
const folderId = resolved.folderExists ? resolved.folderId : created?.id;
if (!folderId) throw new Error('Pasta VP não resolvida');
return [{ json: { id: folderId, folderId, saleId: resolved.saleId, storeFolderId: resolved.storeFolderId } }];

const webhookBody = $('Webhook AgroVenda').first().json.body || {};
const folderId = $('Unificar Pasta VP').first().json.id;
const saleId = String(webhookBody.saleId || '');
const romaneio = String(webhookBody.romaneioNumber || '').replace(/\D/g, '');
const nfDigits = String(webhookBody.nfNumber || '').replace(/\D/g, '');
const incoming = Array.isArray(webhookBody.files) ? webhookBody.files : [];

const existingItems = (() => {
  try {
    return $('Listar Arquivos da Pasta da Venda').all().map((i) => i.json).filter((j) => j && (j.id || j.name || j.Name));
  } catch (e) {
    return [];
  }
})();

function baseName(n) {
  return String(n || '').split('/').pop();
}

function extractNf(name) {
  const n = baseName(name);
  const m1 = n.match(/NF-(\d{6,12})/i);
  if (m1) return m1[1];
  const m2 = n.match(/(?:^|[-_\s])(\d{7,9})(?:[-_\s.]|$)/);
  return m2 ? m2[1] : '';
}

function extractRom(name) {
  const n = baseName(name);
  const m1 = n.match(/^(\d{3,6})-(?:NF|Pedido|CP)/i);
  if (m1) return m1[1].padStart(5, '0');
  const m2 = n.match(/Pedido-(\d{3,6})/i);
  return m2 ? m2[1].padStart(5, '0') : '';
}

function kindOf(name) {
  const n = baseName(name).toLowerCase();
  if (/\bnf[-_]|-nf-/.test(n) || /lancada/.test(n)) return 'nf';
  if (/pedido|canhoto/.test(n)) return 'pedido';
  if (/\bcp\d*[-_]|comprovante/.test(n)) return 'cp';
  return 'other';
}

const existingExact = new Set(existingItems.map((e) => baseName(e.name || e.Name || '')));
const trashIds = new Set();
const incomingNames = new Set(incoming.map((f) => baseName(f.filename || f.originalName || f.name || '')).filter(Boolean));

for (const e of existingItems) {
  const name = baseName(e.name || e.Name || '');
  const id = e.id || e.Id;
  if (!id || !name) continue;
  const k = kindOf(name);
  const eNf = extractNf(name);
  const eRom = extractRom(name);
  const isLegacyVp = /^VP\d+/i.test(name);
  const sameNf = nfDigits && eNf && eNf === nfDigits;
  const sameRom = romaneio && eRom && eRom.replace(/^0+/, '') === romaneio.replace(/^0+/, '');
  const exactIncoming = incomingNames.has(name);
  if ((isLegacyVp && (sameNf || sameRom || (saleId && name.toUpperCase().startsWith(saleId.toUpperCase())))) ||
      (sameNf && k === 'nf' && !exactIncoming) ||
      (sameRom && k === 'pedido' && !exactIncoming) ||
      (exactIncoming && k !== 'cp')) {
    if (!(k === 'cp' && !exactIncoming)) {
      if (k === 'cp') { /* keep distinct CPs */ }
      else if (!exactIncoming) trashIds.add(id);
      else if (k === 'nf' || k === 'pedido') trashIds.add(id);
    }
  }
}

const results = [];

for (const e of existingItems) {
  const id = e.id || e.Id;
  if (id && trashIds.has(id)) {
    results.push({
      json: {
        action: 'trash',
        fileId: id,
        fileName: baseName(e.name || e.Name || ''),
        folderId
      }
    });
  }
}

for (const f of incoming) {
  const contentBase64 = f.contentBase64 || '';
  if (!contentBase64) continue;
  const fileName = f.filename || f.originalName || f.name;
  if (!fileName) continue;
  if (existingExact.has(fileName) && !trashIds.has(
    (existingItems.find((e) => baseName(e.name || e.Name || '') === fileName) || {}).id
  )) {
    continue;
  }

  const fileBuffer = Buffer.from(contentBase64, 'base64');
  if (!fileBuffer.length) continue;

  results.push({
    json: {
      action: 'upload',
      fileName,
      folderId,
      client: webhookBody.client,
      saleId: webhookBody.saleId,
      romaneioNumber: webhookBody.romaneioNumber || '',
      nfNumber: webhookBody.nfNumber || ''
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        fileBuffer,
        fileName,
        f.mimeType || 'application/octet-stream'
      )
    }
  });
}

return results;
